const API=(import.meta.env.VITE_API_URL||'/api').replace(/\/$/,'');
async function api(path:string,opt:RequestInit={}){
  let r:Response;
  try{
    r=await fetch(API+path,{credentials:'include',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});
  }catch{
    throw Error('StockSense backend is not running. Start the backend on http://localhost:4000 and try again.');
  }
  const contentType=r.headers.get('content-type')||'';
  const raw=await r.text();
  let d:any=null;
  if(raw){try{d=contentType.includes('application/json')?JSON.parse(raw):JSON.parse(raw)}catch{d=null}}
  if(!r.ok){
    if(r.status>=500 || !contentType.includes('application/json')) throw Error('StockSense backend is unavailable. Start the backend on port 4000, then refresh this page.');
    throw Error(d?.error||`Request failed (${r.status})`);
  }
  if(d===null) throw Error('The backend returned an empty response. Check that the StockSense API is running on port 4000.');
  return d;
}
const nav=[['dashboard','Dashboard',LayoutDashboard],['products','Products',Package],['receipts','Receipts',ArrowDownToLine],['deliveries','Deliveries',ArrowUpFromLine],['transfers','Transfers',ArrowLeftRight],['adjustments','Adjustments',ClipboardCheck],['intelligence','Intelligence',BrainCircuit],['ledger','Stock Ledger',Activity],['warehouses','Warehouses',Warehouse]] as const;
type User={id:number,name:string,email:string,role:string,created_at?:string};

function Login({onLogin}:{onLogin:(u:User)=>void}){
 const [mode,setMode]=useState<'login'|'signup'|'forgot'|'otp'>('login');
 const [email,setEmail]=useState('demo@stocksense.app');
 const [name,setName]=useState('');
 const [password,setPassword]=useState('Demo@12345');
 const [confirm,setConfirm]=useState('');
 const [otp,setOtp]=useState('');
 const [err,setErr]=useState('');
 const [info,setInfo]=useState('');
 const [demoOtp,setDemoOtp]=useState('');
 const [busy,setBusy]=useState(false);
 const title=mode==='login'?'Welcome back':mode==='signup'?'Create your account':mode==='forgot'?'Reset your password':'Verify your email';
 const clear=()=>{setErr('');setInfo('');setDemoOtp('')};
 const submit=async()=>{
   setBusy(true);clear();
   try{
    if(mode==='login'){
      const d=await api('/auth/login',{method:'POST',body:JSON.stringify({email,password})});onLogin(d.user);return;
    }
    if(mode==='signup'){
      if(password.length<8) throw Error('Password must be at least 8 characters.');
      if(password!==confirm) throw Error('Passwords do not match.');
      await api('/auth/register',{method:'POST',body:JSON.stringify({email,name,password})});
      setInfo('Account created. You can now sign in. New accounts start as Warehouse Staff.');setMode('login');setPassword('');setConfirm('');return;
    }
    if(mode==='forgot'){
      const d=await api('/auth/forgot',{method:'POST',body:JSON.stringify({email})});
      setDemoOtp(d.devOtp||'');setInfo('If that account exists, an OTP has been generated. Check the backend terminal in local demo mode.');setMode('otp');return;
    }
    if(mode==='otp'){
      if(!/^\d{6}$/.test(otp)) throw Error('Enter the 6-digit OTP.');
      if(password.length<8) throw Error('New password must be at least 8 characters.');
      if(password!==confirm) throw Error('Passwords do not match.');
      await api('/auth/reset',{method:'POST',body:JSON.stringify({email,code:otp,newPassword:password})});
      setInfo('Password reset successfully. Sign in with your new password.');setMode('login');setOtp('');setPassword('');setConfirm('');return;
    }
   }catch(e:any){setErr(e.message)}finally{setBusy(false)}
 };
 const selectDemo=(kind:'manager'|'staff')=>{clear();setMode('login');if(kind==='manager'){setEmail('demo@stocksense.app');setPassword('Demo@12345')}else{setEmail('staff@stocksense.app');setPassword('Staff@12345')}};
 return <div className="login"><div className="login-glow"/><div className="login-card auth-card">
   <div className="logo">S</div><span className="login-kicker">INVENTORY OPERATING SYSTEM</span><h1>StockSense</h1><p>{title}. Secure access to your inventory workspace.</p>
   {mode==='signup'&&<input value={name} onChange={e=>setName(e.target.value)} placeholder="Full name" autoComplete="name"/>}
   <input value={email} onChange={e=>setEmail(e.target.value)} placeholder="Work email" autoComplete="email" disabled={mode==='otp'}/>
   {(mode==='login'||mode==='signup'||mode==='otp')&&<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder={mode==='otp'?'New password':'Password'} autoComplete={mode==='login'?'current-password':'new-password'}/>} 
   {mode==='signup'&&<input type="password" value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="Confirm password" autoComplete="new-password"/>}
   {mode==='otp'&&<input value={otp} onChange={e=>setOtp(e.target.value.replace(/\D/g,'').slice(0,6))} placeholder="6-digit OTP" inputMode="numeric" maxLength={6} autoComplete="one-time-code"/>}
   {mode==='login'&&<div className="auth-row"><button type="button" className="text-link" onClick={()=>{clear();setMode('forgot')}}>Forgot password?</button></div>}
   <button onClick={submit} disabled={busy}>{busy?'Please wait…':mode==='login'?'Sign in':mode==='signup'?'Create account':mode==='forgot'?'Send OTP':'Reset password'} <ChevronRight size={16}/></button>
   {mode==='login'&&<><small>Demo access</small><div className="demo-accounts"><button type="button" onClick={()=>selectDemo('manager')}>Inventory Manager</button><button type="button" onClick={()=>selectDemo('staff')}>Warehouse Staff</button></div></>}
   {mode==='forgot'&&<small className="auth-help">We'll never reveal whether an email is registered.</small>}
   {mode==='otp'&&demoOtp&&<div className="otp-demo">Demo OTP: <b>{demoOtp}</b><span>For local competition/demo use only</span></div>}
   {info&&<div className="success">{info}</div>}{err&&<div className="error">{err}</div>}
   <div className="auth-switch">{mode!=='login'&&<button type="button" className="text-link" onClick={()=>{clear();setMode('login')}}>← Back to sign in</button>}{mode==='login'&&<button type="button" className="text-link" onClick={()=>{clear();setName('');setMode('signup')}}>Create a new account</button>}</div>
 </div></div>
}
