 const[logged,setLogged]=useState(false),[user,setUser]=useState<User|null>(null),[permissions,setPermissions]=useState<string[]>([]),[page,setPage]=useState('dashboard'),[notifications,setNotifications]=useState<any>({items:[],unread:0}),[settings,setSettings]=useState<any>(null),[scannerOpen,setScannerOpen]=useState(false),[notificationOpen,setNotificationOpen]=useState(false),[sidebarCollapsed,setSidebarCollapsed]=useState(()=>localStorage.getItem('stocksense-sidebar')==='collapsed'),[mobileSidebarOpen,setMobileSidebarOpen]=useState(false);
 const refreshNotifications=()=>api('/notifications').then(setNotifications).catch(()=>{});
